// Builds the prompt from the tracker's /api/digest.
//
// Division of labour, on purpose:
//   code   every number, the ranking, the "with / against the market" label,
//          the sharpest hour and when it happened -- all computed by the
//          tracker from its own candles.
//   model  prose, and the *reason* for a move -- but only by citing one of the
//          numbered headlines below. Compose turns [n] into a link, and drops
//          any number that does not exist, so an invented source cannot reach
//          the message.
const d = $json;
const coins = (d.coins || []).filter(c => typeof c.price === 'number');
if (!coins.length) throw new Error('digest has no priced coins - is the tracker feed connected?');

const fmt = (p) => {
  if (typeof p !== 'number') return 'n/a';
  if (p >= 1000) return p.toLocaleString('en-US', { maximumFractionDigits: 0 });
  if (p >= 1) return p.toFixed(2);
  return p.toPrecision(4);
};
const pct = (v) => (typeof v === 'number' ? `${v >= 0 ? '+' : ''}${v.toFixed(2)}%` : 'n/a');
const hhmm = (ts) => new Date(ts * 1000).toISOString().slice(11, 16);
const REL = {
  with_market: 'в унисон с рынком',
  outperformed: 'сильнее рынка',
  underperformed: 'слабее рынка',
};

const refs = [];
const line = (h) => {
  refs.push({ url: h.url, source: h.source });
  const when = h.ts ? `${hhmm(h.ts)} UTC` : 'время неизвестно';
  return `[${refs.length}] (${h.source}, ${when}) ${h.title}`;
};

const m = d.market || {};
const marketBlock = [
  `Среднее изменение по ${m.count} монетам: ${pct(m.avg_change)}; в плюсе ${m.up} из ${m.count}; BTC ${pct(m.btc_change)}.`,
  `Лидер роста: ${m.best}. Лидер падения: ${m.worst}.`,
  (m.headlines || []).length
    ? 'Новости рынка за сутки:\n' + m.headlines.map(line).join('\n')
    : 'Новостей рынка не найдено.',
].join('\n');

// Spelled out per coin because a small fallback model otherwise copies the
// example phrase "followed the market" onto a coin that beat it by 2.7pp.
const HINT = {
  with_market: 'Про рынок: можно написать, что монета следовала за рынком.',
  outperformed: 'Про рынок: монета была СИЛЬНЕЕ рынка. Не пиши, что она следовала за рынком.',
  underperformed: 'Про рынок: монета была СЛАБЕЕ рынка. Не пиши, что она следовала за рынком.',
};
const coinBlocks = coins.map((c) => {
  const vs = typeof c.vs_market_pp === 'number' ? `${c.vs_market_pp >= 0 ? '+' : ''}${c.vs_market_pp} п.п. к среднему` : '';
  const out = [`### ${c.ticker} (${c.name}): за 24ч ${pct(c.change24h)}, ${REL[c.relative] || ''} (${vs})`];
  if (typeof c.range_pct === 'number') {
    out.push(`Диапазон за сутки ${c.range_pct}%: максимум $${fmt(c.high)} в ${c.high_at} UTC, минимум $${fmt(c.low)} в ${c.low_at} UTC.`);
  }
  if (c.sharpest_hour) {
    out.push(`Самый резкий час: ${pct(c.sharpest_hour.pct)} (${c.sharpest_hour.from}–${c.sharpest_hour.to} UTC).`);
  }
  if (typeof c.change_1h === 'number') {
    out.push(`Последний час ${pct(c.change_1h)}, последние 4 часа ${pct(c.change_4h)}.`);
  }
  if (HINT[c.relative]) out.push(HINT[c.relative]);
  if (c.health && c.health !== 'ok') out.push(`ВНИМАНИЕ, проблема с данными: ${c.health_note || c.health}.`);
  if ((c.alerts || []).length) out.push('Сработавшие алерты: ' + c.alerts.join(' | '));
  out.push((c.headlines || []).length
    ? 'Новости:\n' + c.headlines.map(line).join('\n')
    : 'Новости: ни одной по этой монете.');
  return out.join('\n');
});

// The heading of each coin (price, 24h change, with/against the market) is
// printed by code. The model is told NOT to restate it: asked to, an 8B model
// turned "outperformed by 2.69pp" into "lagging by 2.69pp".
const system = [
  'Ты криптоаналитик и пишешь утреннюю сводку для Telegram на русском языке.',
  'Цена, изменение за 24 часа и сравнение с рынком уже напечатаны в заголовке каждой монеты. НЕ повторяй их.',
  'Твоя задача для каждой монеты: 1-2 коротких предложения (до 40 слов) —',
  '  а) что происходило внутри суток: самый резкий час, диапазон, сработавшие алерты;',
  '  б) почему: только если причину прямо подтверждает заголовок из списка. Ссылайся номером в квадратных скобках.',
  'Если подходящего заголовка нет, напиши «явных новостных причин нет» и, если монета шла в унисон с рынком, — что она следовала за рынком.',
  'Нельзя: придумывать новости, события и источники; считать причиной прогнозы, рекламу, обзоры и сработавшие алерты (алерты — это наши сигналы, а не новости).',
  'Причина должна совпадать с направлением: рост не объясняют «давлением», падение не объясняют хорошими новостями.',
  'market: 2-3 предложения о рынке в целом и о новостях рынка, которые на него повлияли, тоже со ссылками [n].',
  'Без markdown, эмодзи и HTML. Тикеры латиницей, остальное по-русски.',
  '',
  'Пример хорошего ответа для монеты:',
  '"Резче всего падала с 14:00 до 15:00 UTC, потеряв 2.5% за час. Давление усилилось после новости о расширении сервисов кошелька в Telegram [7]."',
  'Пример, когда новостей нет:',
  '"Самый резкий час — рост на 2.2% ночью, в остальное время торговалась в узком диапазоне. Явных новостных причин нет, монета следовала за рынком."',
].join('\n');

const user = `Данные за последние 24 часа.\n\n== РЫНОК ==\n${marketBlock}\n\n== МОНЕТЫ ==\n${coinBlocks.join('\n\n')}`;

// A schema with one required key per ticker: the model cannot skip a coin.
const schema = {
  type: 'object',
  properties: {
    market: { type: 'string' },
    coins: {
      type: 'object',
      properties: Object.fromEntries(coins.map((c) => [c.ticker, { type: 'string' }])),
      required: coins.map((c) => c.ticker),
    },
  },
  required: ['market', 'coins'],
};

// OpenAI-compatible APIs take no schema, so the expected shape is spelled out
// in the system prompt instead. Built HERE, not in the HTTP node's expression:
// a literal "}}" inside an n8n {{ }} expression ends the expression early and
// the node fails with a bare "invalid syntax".
const shape = '{"market": "...", "coins": {' + coins.map((c) => `"${c.ticker}": "..."`).join(', ') + '}}';
const system_json = system + '\n\nОтветь строго JSON-объектом такого вида: ' + shape;

return [{ json: {
  system, system_json, user, schema, refs,
  market: { avg_change: m.avg_change, up: m.up, count: m.count },
  coins: coins.map((c) => ({ ticker: c.ticker, price: c.price, change24h: c.change24h,
                             relative: c.relative, health: c.health })),
} }];

// Free OpenRouter models sometimes answer HTTP 200 with an error body, or with
// prose instead of JSON. Only a parseable answer carrying both keys goes on to
// Compose; anything else is routed to the local model instead of failing the run.
const r = $json;
let c = r?.choices?.[0]?.message?.content;
let ok = false;
if (typeof c === 'string') {
  c = c.trim().replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
  try { const o = JSON.parse(c); ok = !!(o && o.market && o.coins); } catch (e) { ok = false; }
}
return [{ json: { ...r, ok } }];

// Assembles the Telegram message(s). Headings -- ticker, price, 24h change --
// come from the digest, not from the model, so the model's text can never
// alter a figure. [n] citations become links to the actual article.
const r = $json;
let raw = (r?.message?.content ?? r?.choices?.[0]?.message?.content ?? '').trim();
raw = raw.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
let out;
try { out = JSON.parse(raw); } catch (e) {
  throw new Error('model did not return JSON: ' + raw.slice(0, 300));
}

const p = $('Build prompt').first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (v) => {
  if (typeof v !== 'number') return 'n/a';
  if (v >= 1000) return v.toLocaleString('en-US', { maximumFractionDigits: 0 });
  if (v >= 1) return v.toFixed(2);
  return v.toPrecision(4);
};
const pct = (v) => (typeof v === 'number' ? `${v >= 0 ? '+' : ''}${v.toFixed(2)}%` : 'n/a');
const REL = { with_market: 'в унисон с рынком', outperformed: 'сильнее рынка', underperformed: 'слабее рынка' };

// "[3]", "[3, 5]" or "[3][5]" -> linked source names. A number with no matching
// headline is removed outright rather than left dangling: it would be an
// invented source. Adjacent groups merge, a repeated outlet is linked once,
// and at most two links are shown so a sentence does not end in a wall of them.
const cite = (s) => esc(String(s || '').replace(/<[^>]*>/g, ''))
  .replace(/(?:\s*\[\d+(?:\s*,\s*\d+)*\])+/g, (group) => {
    const seen = new Set();
    const links = (group.match(/\d+/g) || []).map(Number)
      .filter((n) => p.refs[n - 1] && p.refs[n - 1].url)
      .filter((n) => { const k = p.refs[n - 1].source; if (seen.has(k)) return false; seen.add(k); return true; })
      .slice(0, 2)
      .map((n) => `<a href="${esc(p.refs[n - 1].url)}">${esc(p.refs[n - 1].source)}</a>`);
    return links.length ? ` (${links.join(', ')})` : '';
  })
  .trim();

const day = new Date().toLocaleDateString('ru-RU', {
  day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Oslo',
});
const m = p.market;
const blocks = [
  `📊 <b>Криптосводка за 24 часа</b> — ${day}`,
  `🌍 <b>Рынок</b> · в среднем ${pct(m.avg_change)}, в плюсе ${m.up} из ${m.count}\n${cite(out.market) || '<i>нет комментария</i>'}`,
];
for (const c of p.coins) {
  const ch = c.change24h ?? 0;
  const mark = ch > 0 ? '🟢' : ch < 0 ? '🔴' : '⚪';
  const warn = c.health && c.health !== 'ok' ? ' ⚠️' : '';
  const txt = (out.coins || {})[c.ticker];
  const rel = REL[c.relative] ? ` · <i>${REL[c.relative]}</i>` : '';
  blocks.push(`${mark} <b>${c.ticker}</b>  $${fmt(c.price)} · ${pct(c.change24h)}${rel}${warn}\n${txt ? cite(txt) : '<i>нет комментария</i>'}`);
}

// Say which model wrote it, so a weaker fallback day is recognisable as such.
const model = String(r.model || '');
const hosted = model.includes('/');
blocks.push(`<i>🤖 ${esc(model.replace(/:free$/, '') || 'unknown')} · ${hosted ? 'OpenRouter' : 'локально, резервная модель'}</i>`);

// Telegram caps a message at 4096 visible characters (link targets do not
// count). Split on block boundaries so no coin is cut in half.
const visible = (s) => s.replace(/<[^>]+>/g, '').length;
const msgs = [];
let cur = '';
for (const b of blocks) {
  const next = cur ? cur + '\n\n' + b : b;
  if (cur && visible(next) > 3900) { msgs.push(cur); cur = b; } else { cur = next; }
}
if (cur) msgs.push(cur);
return msgs.map((text) => ({ json: { text } }));
